            new Quote { Id = "https://it.wikiquote.org/wiki/Natalia_Ginzburg", Text = "la vecchiaia, che è starsene ripiegati in disparte piangendo lo sfacelo del passato.", Author = "Natalia Ginzburg" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Natalia_Ginzburg", Text = "Pavese commetteva errori piú gravi dei nostri. Perché i nostri errori erano generati da impulso, imprudenza, stupidità e candore; e invece gli errori di Pavese nascevano dalla prudenza, dall'astuzia, dal calcolo e dall'intelligenza.", Author = "Natalia Ginzburg" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Natalia_Ginzburg", Text = "Nulla è pericoloso come questa sorta di errori. Possono essere, come lo furono per lui, mortali; perché dalle strade che si sbagliano per astuzia, è difficile ritornare.", Author = "Natalia Ginzburg" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Natalia_Ginzburg", Text = "è estinta o si sta estinguendo la stirpe dei padri. Da tempo orfani, noi generiamo degli orfani, essendo stati incapaci di diventare noi stessi dei padri.", Author = "Natalia Ginzburg" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Natalia_Ginzburg", Text = "il nostro malcostume ci porta a chiedere all'amicizia, o anche a un semplice sorriso di cortesia, non già il vero ma un nostro immediato vantaggio.", Author = "Natalia Ginzburg" },
